    yearOverview: "By 1863 the Sutton Coldfield Cricket Club had established strong connections with the Free Foresters, reflected in both regular fixtures and mutual respect between the two organisations. That relationship was formally recognised in March, when Bedford was presented with a silver salver inscribed 'In grateful memory of long services and tried friendship this token of esteem is presented to the Rev. W.K.R. Bedford Rector of Sutton Coldfield and sometime secretary of the Free Foresters by his most attached friends & affectionate brethren of the club'. The salver passed into the keeping of MCC at Lord's, where its inscription was confirmed to the Club in May 2021 by Robert Curphey, MCC's Archivist and Library Manager. Beyond the boundary, the year also saw the Rector agree with the Town Council to promote a sports event during a game of cricket in Rectory Park. Advertised as a 'Club Feast', it offered prize money alongside 'General Amusements — Country Dancing, Foot Ball, Cricket, Quoits and other Athletic Sports', with two shillings and sixpence for the winners of the hurdle and flat races for men, and two shillings apiece for the boys' flat races and the sack race. Games commenced at three o'clock, and all disputes were to be referred to the Committee. The event ran for a number of years, though no winners were ever recorded.",
