    yearOverview: "Following a period of decline during the Rector's absence, the Club had become nearly defunct by 1869. Bedford had been away from the town for three years, and his return was announced in the pages of the Church Parish Magazine, where he inserted a notice that survives as the plainest record of the revival: 'A Meeting of the Cricket Club, convened by Circular, will take place on Wednesday, November 3 at 7pm at the Town Hall, for the purpose of taking into consideration the necessary measures for putting into order the Rectory Ground, which is again offered for the use of this club'. The Town Hall then stood in Mill Street, and the wording — 'again offered' — tells its own story of a ground left idle. Supported by his son, the Rector set about restoring the Club's fortunes. Their efforts included relaying and expanding the cricket square, significantly improving playing conditions, while financial support from local benefactors helped stabilise a Club of limited membership. Infrastructure improvements continued with the construction of a dressing pavilion known as 'The Shed', built by the Rector's gardener. Match activity remained limited and not particularly notable in quality, yet the Club's cricketing reach was not negligible: Rev. J.H. Gibbon, one of the Club's own players, was appearing in first-class cricket for Oxford University across 1868 and 1869.",
