    yearOverview: "The year 1910 marked a historic transition with the retirement of Rev. W.C.R. Bedford as President, ending over six decades of leadership by the Bedford family. His departure represented the conclusion of a defining era in the Club's history, during which the family had guided its development from inception to stability. On the field the Club enjoyed a successful season, with strong batting performances led by L.C. Crockford, J.B. Russell and E.B. Crockford, while the bowling was equally effective, Dr. Sproat and others delivering consistent results. It was also the year in which the Club acquired its finest recorder. Norman Sharp, whose father George Sharp had moved into Sutton and joined the Club in 1905, bringing his four-year-old son with him, became 2nd XI scorer in 1910; many of the pre-First World War score books were completed in his hand, and he appears on many of the pre-war team photographs. Around him the next generation was gathering: Harold Edward Robinson, born in 1908 close to the Boot public house, was growing up with Rectory Park for a playground, while M.K. Foster, another Sutton Coldfield player, had begun in 1908 a first-class career that would take him to Worcestershire, MCC and an England XI. The Club also maintained a strong social calendar, including the Annual Dinner and Smoking Concert.",
