    yearOverview: "In 1911 the Club entered a new phase under the presidency of Rev. Canon C.W. Barnard. The transition reflected its ability to continue beyond its founding family while maintaining continuity in leadership and organisation. On the field the season included notable performances, among them a remarkable bowling sequence against Nuneaton in which multiple wickets fell in consecutive deliveries. Players such as J.B. Russell and E.B. Crockford continued to contribute significantly, while Frank Hanmer emerged as a leading fast bowler. Crockford's own rise was the story of the summer: Eric Bertram Crockford, known as Tom, began in 1911 a first-class career with Warwickshire that would extend to 1922, and he would go on to win an Olympic gold medal in the hockey tournament at Antwerp in 1920, representing England on seventeen occasions and holding a number of records for the highest break at billiards. The year also highlights the character of the side he played in — men drawn mostly from the professions, among them the clergy, the medical profession, ex-military officers, accountants and solicitors, Aldermen, Councillors, Justices of the Peace and former Mayors of Sutton Coldfield — alongside club characters such as C. Lowe, whose enthusiasm and long service embodied the spirit of amateur cricket.",
