    title: "The Great War and Club Resilience",
    shortDescription: "The declaration of war transformed the Club's activities: members enlisted in great numbers, regular fixtures gave way to scratch sides and service elevens, the clubhouse sheltered the wounded, and the losses were grievous.",
    yearOverview: "The outbreak of the Great War on 4th August 1914 brought a profound and immediate impact on the Club, as cricketing activity was largely overshadowed by national service. A great number of members answered the call, most of them signing up immediately after the declaration of war, and the Club's losses were grievous; accounts differ sharply on the exact figures, with contemporary records, later recollection and modern research each giving a different reckoning of how many went and how many came home. Their sacrifice became an enduring part of the Club's history. Despite these losses, which meant the Club nearly lacked the manpower to reconvene in 1919, it did not cease to function. A small group of dedicated members, led by figures such as George Sharp, ensured its survival by maintaining the ground and organising limited cricket when possible. Convalescent camps were built in Sutton Park so that injured soldiers might recuperate before returning to their units, and across the four years of the war some 90 officers and 3,000 men were billeted in the park. The clubhouse itself was used by wounded men during their recovery, and a photograph of it in that service survives. What matches there were consisted mainly of scratch sides playing against service elevens stationed in the locality, while fixture cards gave way to circulars and subscription income fell away.",
