    shortDescription: "Club operations were reduced but never abandoned, with circulars issued in place of fixture cards — while members of the Club fell at the Somme, near St Julien and, in Shenton's case, of wounds after coming home.",
    yearOverview: "During the war Club operations were reduced but not abandoned. Fixture lists were replaced by circulars because of the uncertainty of matches, games were played mainly against service teams, and financial contributions declined sharply, reflecting reduced membership and wartime pressures. Dedicated individuals such as George Sharp ensured continuity in administration, and a Roll of Honour was established to recognise members serving in the forces, though it was later lost. Fundraising for wartime causes continued, including a post-war garden fête in aid of medical services. Meanwhile the roll of loss lengthened. Percival A. Grove, the Hon. Secretary, was killed in 1916, and Arthur J. Lilly, Hon. Treasurer since 1906 until he joined the Birmingham City Battalion, made the supreme sacrifice at the Somme that same year. Horace Shenton entered France on 21st November 1915, was wounded by shrapnel in the back on 31st August 1916 and returned to England for an operation in Leeds; he died of his wounds on 27th August 1917, aged 38, and lies in Sutton Coldfield Cemetery. Albert Edward Wakefield of Mere Green Road, who played for the Club's 'A' team, was killed at 2.30am on 17th August 1917 near St Julien, aged 20; he has no known grave and is commemorated on the Tyne Cot Memorial. In 1917 a meteorite struck the huge ash tree standing between the two grounds.",
