    yearOverview: "Following the end of the war the Club resumed normal operations, though with significant losses among its members, so severe that it nearly lacked the manpower to reconvene at all. The deaths of key figures such as Percy Grove and Arthur Lilly were deeply felt, both having played important administrative roles. Attention turned to rebuilding: appointing a groundsman, restoring facilities and re-establishing fixtures, while financial recovery came gradually, with revised subscription rates introduced to stabilise income. A memorial tablet was proposed and accepted to honour those who had lost their lives, reflecting the Club's commitment to remembrance. In the same year Norman Sharp reported that 'for many years an impressive Roll of Honour of those who served and gave their lives adorned the Pavilion, but unfortunately was destroyed by hooligans' — and, since no record of the names was ever set down in writing, the identities of many who served were lost with it. Sharp himself, captain of Bishop Vesey's Grammar School in all its sporting activities until he left in 1919, became a full member of the Club that year; after a season's graduation with the 'A' and 2nd teams he would settle as the regular right-handed opening batsman of the 1st XI, and thereafter missed scarcely a committee or general meeting for the rest of his life.",
