    yearOverview: "Cricket resumed with renewed enthusiasm, though the effects of the war were still evident in reduced player availability. Nevertheless a strong side was assembled, with key players such as F.B. Clark, E.B. Crockford and H. Lott returning to action. Clark excelled as an all-rounder, scoring 814 runs and taking 74 wickets, while others contributed significantly with both bat and ball; strong support came from Crockford and Beardshaw. The first team played twenty-one matches, winning eight, losing seven and drawing six, and the Club's structure, including midweek cricket, was gradually restored. The second team faced challenges through mismatched opposition but continued to compete regularly. Clark's summer was of a piece with a career that stands among the finest the Club has known: a fast-medium seam bowler who swung the ball late both ways and was feared by most club batsmen, he lived at Aldridge and so did not qualify for a first-class county, but was a regular with Staffordshire, and across a membership spanning sixty-two years he took over a thousand wickets and made well over ten thousand runs. The score books of the 1919 season survive in the Club's keeping, a rare and precious record of the summer in which Rectory Park came back to life.",
