    shortDescription: "Despite a small financial loss, 1923 proved a successful season in cricketing terms, with Crockford averaging over 50 — and it gave Norman Sharp his single, unrepeated appearance in first-class cricket, for Warwickshire at Edgbaston.",
    yearOverview: "The 1923 season saw strong batting performances, with several players achieving high averages and multiple centuries recorded. E.B. Crockford led the batting with an average exceeding 50, supported by Leighton and Russell. Despite success on the field, financial pressures persisted, resulting in a recorded loss for the year. Efforts to raise funds included events such as a Club dance and benefit subscriptions for the groundsman, while administrative decisions addressed such matters as car access to the ground and costs shared with other organisations. The season's most singular honour, however, fell to Norman Sharp. Selected by Warwickshire to face Worcestershire in the County Championship at Edgbaston, he made his one and only appearance in first-class cricket. Batting just once, from a low position in the order, he scored 3 before being bowled by Leslie Gale, in a match Warwickshire won by seven wickets. It was the briefest of entries in the record books for a man who would gather nearly 25,000 runs in club cricket, 19,710 of them for Sutton Coldfield, and who would in time fill almost every office the Club had to offer. Far away at Battle in Sussex, on 15 December, Philip G. Berry was born; half a century later he would be among the most familiar umpires at Rectory Park.",
