    yearOverview: "In 1927 the Club experienced a period of transition marked by both departures and organisational change. J. Hartley Yates ended his long association with the Club, having been a prominent first team player before continuing as a Vice President. More significantly, the sudden death of Norman Marsh, the Honorary Treasurer, represented a major loss after many years of dedicated service; his contribution was widely recognised, and a pavilion clock was later installed in his memory. Changes in leadership followed, with R.T. Janney stepping in as acting treasurer, while F.H. Beardshaw relinquished the secretary role after three years of service. A.F. Leighton assumed the captaincy of the First XI, bringing strong leadership to the side. On the field performances remained solid, with multiple victories and consistent contributions from key players, alongside the continued development of emerging talent. A quieter appointment proved among the most enduring of all: when Eustace Felton retired as First XI scorer, Harold Robinson took over the book. Robinson had lost his right arm the previous year, falling between a moving train and the platform, yet he scored, and a few years later, when Jack Garland retired, took up the umpire's coat — the beginning of a career that would carry him into the front rank of English umpiring. Geoff Pritchett, a wicketkeeper-batsman who would join Sutton twenty years later, was born that year.",
