    shortDescription: "The 1928 season stands among the finest in Sutton Coldfield's history: six centuries in a summer, more than a thousand runs for N. Sharp, and a side against Olton containing seven county cricketers and one who had played for England.",
    yearOverview: "The year 1928 saw outstanding performances on the field and further changes in leadership. Rev. Canon C.W. Barnard was re-elected President but passed away later in the year, marking the end of an important era, while subscription structures were revised at the AGM, reflecting the Club's evolving financial organisation. On the field the season was notable above all for exceptional batting. The arrival of M.K. Foster, a distinguished county cricketer, added further strength even though his appearances were limited, and N. Sharp achieved a remarkable milestone by becoming the first Club member to score over 1,000 runs in a season, including a sequence of six consecutive high-scoring innings. Six centuries were recorded by the First XI across the summer, a Club record that would stand for forty-five years, and E.H. (Ted) Walters enjoyed the finest season of his long career, averaging 41. Paul I. Terry and A.F. Leighton set a Club record for the eighth wicket. The depth of talent was extraordinary: the side that took the field against Olton & West Warwickshire contained seven players who had appeared in county cricket and one who had played for England. D.G. Foster, meanwhile, began a first-class career with Warwickshire and the Gentlemen that would run until 1934. The batting strength of 1928 was widely regarded as among the strongest in the Club's history.",
