    yearOverview: "The 1930 season marked an important period of transition for the Club, particularly in its administration. After three years of strong service, R.T. (Bob) Janney stepped down as Hon. Secretary and was succeeded by E.H. (Ted) Walters, a younger member already establishing himself in the side. Walters proved an energetic administrator through a decade in office to 1940, a post that then embraced supervision of the groundsman and all matters appertaining to the running of the Club, and he balanced it with regular appearances in the first eleven. Norman Sharp, meanwhile, succeeded his own father as fixture secretary, beginning eighteen unbroken years in the office. The year also brought the passing of an old friend: Edward Ansell, elected a playing member in 1888 and long a Vice President, whose death was recorded at the AGM of 20 March. The Ansell family's 290-acre Moor Hall estate was auctioned that year for £35,000, the mansion becoming a hotel and the park the golf course it remains. Beyond the boundary the town was changing too, Bedford Road being built at about this time along the track known as Blackberry Lane. On the field the Club continued to benefit from strong batting, while new talent emerged, notably D.G. Foster, a powerful fast bowler and aggressive batsman whose performances for both Sutton and Warwickshire marked him out. Poor weather affected several late-season matches, but the standard of cricket remained high.",
