    title: "A Difficult Campaign and a Famous Farewell",
    shortDescription: "Results proved disappointing in a demanding campaign, with only three victories from twenty-four matches, but the Free Foresters returned to Rectory Park and F.B. Clark closed one of the greatest of all Sutton careers.",
    yearOverview: "The 1935 season proved one of the more challenging of the decade. Despite possessing capable players, the team struggled to convert performances into results, managing only three wins from twenty-four matches. There were still moments of quality — R.F. Barnes made 101 not out, and there were strong partnerships — but these were overshadowed by heavy defeats and inconsistent batting. A notable highlight was the return of the Free Foresters fixture, bringing to Rectory Park the wandering club founded on that very ground in 1856 by Sutton's own founder-president, the Rev. W.K. Riland Bedford. In a two-day match the Foresters were all out for 364, a total long remembered as among the highest made by any visiting side against the Club's First XI. The season also marked the retirement of F. Bernard 'Bengy' Clark after many years of outstanding service. A fast-medium seam bowler who swung the ball late both ways, feared by most club batsmen, he had taken over a thousand wickets in the days before Sunday play — his best return 10 for 35 against Yardley in 1914 — made well over 10,000 runs, and in his more active days fielded brilliantly at cover point. Resident at Aldridge, he never qualified for a first-class county but was a regular with Staffordshire, and his membership of Sutton Coldfield spanned sixty-two years.",
