    title: "Berlin Gold in a Drowned Summer",
    shortDescription: "One of the wettest summers on record wrecked the fixture list, yet the season belongs to Godfrey Brown of 146 Rectory Road, who came home from the Berlin Olympics with relay gold and an individual 400 metres silver.",
    yearOverview: "The 1936 season was heavily disrupted by exceptionally poor weather, making it one of the most challenging years for cricket in the period. Large portions of the season were lost, including a prolonged mid-summer spell of several weeks in which no play was possible at all, and the lack of continuity told: the team could not build momentum, only three wins were recorded, and occasional strong displays — a convincing victory over Ashfield among them — were offset by heavy defeats in the return fixtures. Despite the conditions the Club fulfilled its fixtures where it could and maintained its competitive spirit, including a closely fought match against the Free Foresters. Away from the sodden outfield, however, the summer of 1936 brought the Club the greatest distinction in its athletic history. At the Olympic Games in Berlin, Arthur Godfrey Kilner Brown, a member of the Club who lived at 146 Rectory Road, won a gold medal in the 4 × 400 metres relay and a silver in the individual 400 metres. At twenty-one he was the youngest member of the British relay quartet, yet was entrusted with the testing anchor stage, and he ran it to gold. His sister Audrey took a silver medal at the same Games, making the family's Berlin a remarkable one. M.K. Foster, whose distinguished first-class career had begun in 1908, played his last such cricket that year.",
