    yearOverview: "The 1938 season was notable not only for its cricket but for developments that would shape the Club's long-term future. On the field the team, under the captaincy of C. Howl, performed admirably despite a side reckoned weaker than the Club's usual standard; through effective leadership and tactical awareness it secured ten victories and, unusually, completed every fixture without abandonment. The batting produced the finest partnership of the pre-war years: away at Stratford, N.F. Prosser made 100 not out and E.H. Walters 87 not out in an unbroken stand of 200, recorded in the Club's books as its highest partnership before the Second World War. Off the field the Club faced a serious threat when it emerged that Rectory Park might be sold for building development. This caused considerable concern, but the situation was ultimately resolved when the Corporation purchased the land to preserve it as a public open space, ensuring the continued existence of cricket on the ground. In the committee room, Frank Styles completed nine years as Hon. Treasurer, an office he had held since 1929. The Club's Olympian was meanwhile at his peak: Godfrey Brown went unbeaten through 1938, took both the AAA and the European 400 metres titles, added a silver medal in the 4 × 400 metres relay at the European Championships, and was reckoned by some to be the world's leading quarter-miler of the year.",
