    yearOverview: "The 1939 season began under growing international tension and ended abruptly with the outbreak of the Second World War. Despite the uncertainty the Club played a good number of matches, many producing exciting and high-quality cricket. There were notable individual performances, particularly from Roy Baker, whose rapid scoring — 97 in forty-three minutes — made a strong impression. The experimental eight-ball over was trialled during the season, though it did not prove popular, and D.H. Twiss took over as Treasurer. The deaths of Rev. A.E.R. Bedford and H.L. Mortimore added to the sombre tone of a difficult year. It was also the last Sutton season of Godfrey Brown, whose appearances for the Club had run from 1933; he had married Mary Denholm Armstrong early in the year and become a schoolmaster, and on the track, after winning the AAA 880 yards title in a modest time, he ran the final major race of his career, finishing fourth and last in the 400 metres against Germany at Cologne. When war was declared in September the remaining fixtures were cancelled, bringing the season — and effectively the era of peacetime cricket — to a close. Harold Robinson, the Club's scorer turned umpire, moved south at the outbreak, and the horses that had drawn the heavy roller across Rectory Park for the better part of a century worked their last seasons.",
