    yearOverview: "The outbreak of the Second World War brought immediate disruption to normal cricketing life, yet the early phase of the conflict — often called the \"Phoney War\" — allowed the Club to continue playing through 1940. Travel restrictions, particularly the limited petrol allowance, meant that long-distance fixtures were largely abandoned in favour of local opposition. Despite the uncertainty Sutton still fielded two teams, in large part because many older members had not yet been called up, and this allowed competitive and enjoyable cricket to continue under constrained conditions. Matches were often spirited, including a tied game against Olton at 87 apiece and a strong batting display against Kings Heath in which N. Sharp made an unbeaten 115. Administratively the Club remained stable, with most officers continuing in their roles, though E.H. Walters's decade as Hon. Secretary came to an end with the war and his own war service; he did not play often afterwards but kept a keen interest to the last. A.J. Terry took the 2nd XI captaincy. The year also saw the departure of Frank Styles, Hon. Treasurer from 1929 to 1938, a J.P. in the town and manager of the High Street branch of the Midland Bank, who had been largely responsible for the erection of the lower ground pavilion on its present site; he retired to his beloved Snowdonia, retaining his association with the Club as an Hon. Life Member.",
