    yearOverview: "The Club's centenary in 1947 was a landmark occasion, celebrated with a week of cricket and social events that reflected both a proud history and a renewed vitality. Extensive efforts were made to prepare the ground and facilities, and although the general standard of cricket remained below pre-war levels, improvement was evident. The festival week, from 14 to 19 July, featured matches against the MCC, the Warwickshire Imps and the Free Foresters — the last a particularly fitting guest, for that wandering club had itself been founded on this ground in 1856 by Sutton's founder and first President, the Rev. W.K. Riland Bedford. A commemorative painting was presented. The season saw a resurgence in results after a poor start, L.W. Stevenson took 86 wickets, and the retirement of Clifford Howl ended another significant playing career. The centenary year brought change in the committee room too: Norman Sharp completed eighteen years as fixture secretary and was elected Sutton's representative on the Warwickshire County Cricket Club committee, a seat he would hold until 1972. Geoff Pritchett joined the Club at the age of twenty as a wicketkeeper-batsman, beginning in the 2nd XI. In the wider Midlands game, W. Leslie Jones — a friend of Sutton whose influence later brought the Club several grants — founded the Midlands Club Cricket Conference, serving as its only Hon. Secretary as it grew towards seven hundred clubs.",
