    yearOverview: "The early years of the Club's second century were focused on consolidation and rebuilding. While the ground and facilities continued to improve, financial pressures remained a major concern and required constant fundraising. Leadership remained strong, though the sudden death of President Wilfred Bigwood was a significant loss; his successor, A.E. Terry, brought continuity and a deep connection to the Club. On the field results did not reflect the gradual improvement in playing strength — only four wins came from twenty-seven matches, and batting remained a weakness — but bowling performances were consistently strong and the junior and 2nd XI ranks were growing. The season closed Norman Sharp's captaincy of the First XI, an office he had held for eight seasons since 1941. He was a batsman above all, scoring 19,710 runs for Sutton of which 13,067 were for the First XI, and nineteen centuries, fifteen of them at the top level; he rarely bowled, yet in one celebrated match against Aldridge at Rectory Park, with the visitors 50 without loss in reply to 158 for 7 declared, he removed the first six batsmen in quick succession, returned to take three more and finished with 9 for 35 as Aldridge closed on 95 for 9. That year he was also recorded among the founding members of the Midlands Club Cricket Conference, the body he would later serve as chairman and president.",
