    yearOverview: "The 1953 season marked a period of significant expansion, both in playing numbers and in overall club activity. The revival of the Annual Dinner reflected a renewed social dimension, while the introduction of a Sunday third team meant that Sutton was now fielding up to seven sides on some weekends — an indication of remarkable growth. On the field, performances across all teams were exceptionally strong, with five players exceeding 1,000 runs and 56 wins from 117 matches reflecting a high standard of cricket throughout the club. Chief among the run-makers was Geoff Pritchett, who by now had settled as a first-team opening batsman: he scored 1,280 runs in the season, 914 of them on Saturdays and 366 on Sundays, and made 106 at home against Leamington. The season also saw Peter Yates's name appear in the 1st XI for the first time, a left-arm medium-fast swing bowler who moved the ball both ways and was a very useful batsman, and who would go on to play both Saturdays and Sundays through to the end of the 1962 season. Behind the scenes, Alex Harvey came to the club as groundsman, beginning a long and loyal service; improvements continued to the tea pavilion, and the role of the club's ladies was increasingly recognised as vital to both operations and finances. Further afield, Harold Robinson — the club's former scorer and umpire — was involved with Tom Smith and Douglas Jardine in setting up the Association of Cricket Umpires.",
