    yearOverview: "By 1954 the club's revised team selection and development policy, introduced in earlier years, began to show clear results. The focus on balancing teams and promoting youth led to a significant increase in membership, particularly among younger players, helping to secure the club's long-term future. Despite extremely poor weather, which cost 41 matches, individual performances remained strong: V. Fitzgerald took 10 wickets for 18, and Geoff Pritchett made 113 not out away at Market Drayton. The year also marked the retirement of long-serving players including G.V. Swift and B.T. Wood, both of whom had played key roles in the club's history, particularly during the post-war period. Swift's departure had a direct consequence, for it was on his retirement that Pritchett — who had joined in 1947 as a wicket-keeper batsman but had been kept out of the gloves — finally became the first-team keeper, and in that first season behind the stumps the club's records credit him with 14 catches and 38 stumpings, a total of 52 victims. Norman Sharp captained the \"A\" side and was elected chairman of the Midland Club Cricket Conference following the retirement of Guy Heaton of Harborne C.C., the Conference by then embracing more than three hundred clubs. Elsewhere, Roger Coombs received his National Service call-up papers and was posted to the Berlin area, where he became an important player in his regiment's cricket and hockey sides.",
