    shortDescription: "H.A. Couchman became the first Chairman of the Club but died in office that June; the year ended with amalgamation with the Hockey Club agreed to fund a new pavilion.",
    yearOverview: "At an Extra-ordinary General Meeting prior to the 1967 AGM the new office of Chairman of the Club was created, distinct from the long-standing Chairman of Committee, and H.A. Couchman was elected to fill it — but died suddenly in June, only weeks into office. C.T. Groves succeeded Roddy Wilson as General Secretary, the Annual Dinner welcomed M.J.K. Smith, the Warwickshire and England captain, and a treasurer's loss of £120 was reported. The weather then intervened: the press described May as the wettest in 190 years, and nineteen fixtures across all teams were rained off in the month. The 1st XI managed only nine wins from thirty-nine matches and a remarkable tie against the Old Edwardians, the last batsman run out with the scores level on 140. Martin Bloomer's 129 against Harborne provided the only century of the season. Off the field, two long-running negotiations turned decisive: protracted talks with the Rugby Football Club collapsed when their minimum capital demand reached £25,000, and a fresh approach to the Hockey Club led by year-end to a formal amalgamation. The new \"120 Club\" lottery and an Autumn Fare in Fellowship Hall added to a pavilion fund of around £1,500.",
