    shortDescription: "Cricket and hockey clubs formally amalgamated in April and plans for an £11,000 pavilion were approved as the ground lease was extended by seven years, while Neil Houghton made a century and took a hat-trick in the same match.",
    yearOverview: "1968 saw the long-discussed amalgamation of the Cricket and Hockey Clubs formally confirmed in April, with Norman Sharp elected President of the new Association, Charles Groves Hon. Secretary and H. Ford Hon. Treasurer. A Building sub-committee then submitted plans for a pavilion costing a little over £11,000, to be erected by Lessar Bros. Ltd, with six dressing rooms, a club room and the customary amenities — plans unanimously approved by a membership that had waited years for them. The Town Council extended the ground lease by a further seven years, taking it to twenty-eight, and a £500 grant, the maximum available, was secured from the Midlands C.C.C.; with contributions from the \"120 Club\" and the hockey club, about £9,000 was already in hand. On the field the weather was again poor and every 1st XI Saturday match was rained off, but the Annual Dance produced a record £234 profit on the back of the \"120 Club\" Mini car draw, won by Mrs. L. Balmer. Neil Houghton produced the rare feat of a century and a hat-trick in the same match against Walsall, Michael Dixon made 183 not out for the Hawks, Martin Bloomer scored 623 runs, and Peter Wells took 6 for 7 for the 2nd XI away at Bromsgrove. The former Yorkshire and England opener Frank Lowson joined but, at 42, did not make the grade.",
