    shortDescription: "The 1st XI's most successful season on record, but on the eve of demolition the old thatched pavilion was completely destroyed by fire.",
    yearOverview: "Under Martin Bloomer's captaincy the 1st XI produced its most successful season on record with twenty-three victories. Two new arrivals strengthened the side significantly: A. (Tony) Robertson, an attacking batsman who scored a century and a 96 not out on the same weekend, and T. Jameson, brother of the Warwickshire player, who brought medium-pace bowling to the attack. Chris Barber, Michael Dixon and Roy Catt all had good seasons, and Jamie McDowall represented Cambridge University as wicket-keeper and opening batsman, and Warwickshire's 2nd XI as keeper. The Cricketers Cup, the new Derrick Robins national knock-out, saw Sutton enter for the first time and exit at Lichfield in conditions of torrential rain and complete darkness. The dominant event of the year was off the field. After the new pavilion's funding had been secured through a successful Appeal — donations, loans against annual prize draws, and paid-up life memberships — the old building was stripped and contractors moved on site in early November. The day before demolition, a spark from a workmen's brazier set the old thatched pavilion alight and completely gutted it; the groundsman Alex Harvey was inside but came to no harm.",
