    shortDescription: "Edmund H. King cut the tape on the new pavilion on 25 July, Martin Bloomer made 159 against Walsall, and Warwick Tidy carried off the Sir Frank Worrell Trophy as the most promising young cricketer in the country.",
    yearOverview: "Delayed through the winter by weather, drainage and inevitable setbacks, the new pavilion was usable when the season opened but in a somewhat chaotic state; members of both the cricket and hockey clubs worked through to the end of May to make it presentable, and the official ceremony followed on the evening of Friday 25th July. Edmund H. King, Chairman of Warwickshire C.C.C. and in earlier days a county cricketer and hockey player, cut the tape before a large gathering that took in the Mayor and Mayoress, Alderman and Mrs H.J.C. Musgrave, officials of Warwickshire C.C.C. and the Midlands Club Cricket Conference. Arthur Spencer, President of the Hockey Club, deputised for Norman Sharp, ill in hospital, and the evening closed with a tankard for Charles Groves in recognition of his services to the undertaking. Paving slabs and turfing followed in the autumn at the expense of the playing member Joe Holman, while Bob Wilkinson took over the roses and flower beds from Pat Bowerbank, who left after twenty-one years for an appointment in Surrey. On the field Martin Bloomer's 1st XI won 18 of 41 matches, drawing 10, losing 13 and tying one; Bloomer (ave. 35) made a fine 159 against Walsall, Michael Dixon (ave. 33) passed a thousand runs as an opener, and Tom Jameson averaged 27 with 37 wickets. Warwick Tidy, claimed by the County midweek but free most Sundays, took the Sir Frank Worrell Trophy, and the Club marked it with a tankard.",
