    shortDescription: "The pavilion account closed at £16,369, Alex Harvey retired after eighteen years as groundsman, and a handful of members quietly signed Sutton up to league cricket for the first time in over 120 years.",
    yearOverview: "Peter Cadman, the Association's Hon Treasurer, opened the New Year by putting a figure to the great undertaking: £15,752 spent on the pavilion, with a further £617 on furnishings and equipment, £16,369 in all. The Annual Dinner was held in the new building for the first time, outside caterers engaged and the affair voted a success, with M.J.K. Smith, the former England and Warwickshire captain, as Guest of Honour, supported by Edgar N. Hiley of the Warwickshire Supporters Association. At the A.G.M. the Hon Secretary's report paid tribute to the ladies, who had raised a great deal towards the building and made £100 profit on teas; Norman Sharp was re-elected President, Bob Nuttall became Chairman and took on Pat Bowerbank's old duties as Hon Ground Secretary, and Roger Coombs succeeded Martin Bloomer as 1st XI captain with James McDowell as his deputy. Arthur Spencer was elected President of the Association and, after Sharp's twenty-five years in the office, Sutton's representative on the Warwickshire C.C.C. committee. Alex Harvey, groundsman since 1953 and a man who would help behind the bar after a tiring weekend, retired with a handsome testimonial, the playing member Richard Bradshaw taking his place. July brought a Gala Day of donkey derby, target golf and treasure hunt under a warm sun, worth a few hundred pounds to the funds, while Peter Bell's new Sutton News Cup drew sixteen leading Midland clubs.",
