    shortDescription: "Keith Gardom left the county game to captain Sutton and made 1,285 runs; Michael Dixon, free of the captaincy, made 1,298. Between them the 1st XI recorded eight centuries in a season — a new club record.",
    yearOverview: "The Annual General Meeting opened with a minute's silence for Norman Sharp, the Club's President, historian and opening batsman of thirty years, who had died the previous July. Geoff Pritchett was elected to the presidency in his place, Andy Blaygroves succeeded Neil Houghton as Hon Secretary, and Michael Dixon stood down after five years in charge of the 1st XI in favour of Keith Gardom; a small number of Owls fixtures were arranged for the latter part of the season, with Mike Moore to lead that side when required. The Annual Dinner followed on Friday 27th January in the pavilion, Ron Smith in the chair, with Athol Butters of the M.C.C.C. and Leicester Ivanhoe proposing the toast to the Club and John Payne replying, and Stan Petch and David Dollery of Knowle & Dorridge exchanging flamboyant toasts to the guests. Gardom, who had chosen the family business over a Warwickshire contract, proved the ideal successor as captain and made 1,285 runs, with 109 away at Harborne, 105 not out at home to Stratford and 102 not out at Lichfield. Dixon, batting without the cares of leadership, amassed 1,298: 101 not out and 109 not out at home to Stratford and Olton, 117 not out against Bromsgrove and 120 at Stratford. Graham Tidy added 100 not out against Aldridge, and the eight centuries were a new 1st XI record.",
