    shortDescription: "The Hawks took the M.C.C.C. championship again, the Sunday second eleven won the Warwickshire Sunday League, and Mick Hooper made an unbeaten hundred for the Conference at Chedworth’s centenary.",
    yearOverview: "The season began with a party. Nearly a hundred members, officials and guests filled the Penns Hall Hotel on Friday 26 January, the awards ceremony the highlight of the evening: Andrew Luckhurst carried off both the first team’s batting and bowling awards, Alan Jerman took the second eleven batting prize and Michael Mackey the bowling, Steve Russell was voted Clubman of the Year, and Ian Woods was congratulated on the manner in which he had led the Hawks to the Chesshire Gibson League title. The annual general meeting that followed changed almost nothing, save that Paul O’Connor was leaving the district and D. Worsfold took over the fixture secretary’s file. What followed was a year of silverware at every level of the club. Sutton won the Warwickshire Winter Six-a-Side indoor league before a ball had been bowled outdoors; the second team won the Warwickshire Sunday League; the third team, the Hawks, won the M.C.C.C. league championship again; and a joint side of Hawks and Grasshoppers carried off the Jubilee Shield. Geoff Pritchett was named Cricketer of the Year by the Midland Club Cricket Conference, and Mick Hooper, chosen by the Conference for their match against Chedworth, the Cotswold village club celebrating its centenary, marked the occasion with 100 not out. The Sunday second eleven, captained by Chris Barber, with Bob Strachan, Mick Hooper, Ken Lancaster, Adrian Colledge, the Jerman brothers, Jonathan Miller and Chris Munn, were champions in this season and the next.",
