    title: "Bacher’s Summer, and a Title in Waiting",
    shortDescription: "Adam Bacher, a South African who would go on to open the batting in nineteen Test matches, was engaged as professional, and a committee returned unopposed settled in behind a side that was one season from the championship.",
    yearOverview: "It was, on the face of it, the quietest of years. The annual general meeting introduced no changes at all: every officer stood for election and every officer was returned unopposed, leaving Geoff Pritchett as President, Mike Hepburn in the chair, James Ross as secretary and Paul McCarthy as fixture secretary, with Andy Luckhurst leading the first eleven, Adrian Colledge the second and Ian Nicholls the Hawks. The annual dinner went entirely unrecorded. Yet the one piece of business the meeting did transact mattered a great deal: Adam Bacher, from South Africa, was to be engaged as the club’s overseas professional — a young batsman who would play nineteen Test matches and twenty-one one-day internationals for his country, and who would open for South Africa against England at Lord’s on 18 June 1998, in his sixteenth Test. He arrived at a club on the rise. Luckhurst had taken the first eleven captaincy in 1990 and would hold it for four seasons of rare success, the side having finished runners-up in the Warwickshire Sunday League the previous summer. What Bacher joined, and what the following season proved, was one of the strongest teams in the club’s long history: in 1993, using only about fifteen players and losing a single match all year, Sutton won the Willis Corroon M.C.C.C. League Championship under Luckhurst, with the Hawks taking the third eleven title in the same summer. The pieces, in 1992, were quietly assembling.",
    keyEvents: [
      "The annual general meeting made no changes to the committee — all officers stood for election and were returned unopposed",
      "Adam Bacher of South Africa was engaged as the club’s overseas professional for the season",
      "Bacher went on to play nineteen Test matches and twenty-one one-day internationals for South Africa",
      "He opened the batting against England at Lord’s on 18 June 1998, in his sixteenth Test, and made 22",
      "Geoff Pritchett remained President, standing down only at the 1993 annual general meeting after 47 years as player and officer",
      "Mike Hepburn continued as chairman, James Ross as secretary and Paul McCarthy as fixture secretary",
      "Andy Luckhurst, first eleven captain since 1990, continued in charge; Adrian Colledge led the second eleven and Ian Nicholls the Hawks",
      "The first eleven had finished runners-up in the Warwickshire Sunday League the previous season",
      "The following summer the same side won the Willis Corroon M.C.C.C. League Championship, losing only one match all season and using about fifteen players",
    ],
    closingSummary: "A year of no upheaval and one signing — but the settled committee and the settled side were exactly what the championship of 1993 was built on.",
    location: "Rectory Park, Sutton Coldfield",
    imageCaption: "Adam Bacher, the South African batsman engaged as Sutton Coldfield’s overseas professional for the 1992 season, and later a Test opener for his country.",
