      "Randall makes 126 out of 241 against Aston Unity, who are then bowled out for 39 in 15 overs",
      "2nd XI declare on 365 for 8 at Griff & Coton — Bobby Arif 165 not out and Abdul Raqib 114 adding 156 in 18 overs",
      "Bilal Aziz scores 212 as the 2nd XI make 340 for 6 at home to Kings Heath",
      "Bobby Arif finishes the season with 510 runs at an average of 51.0, including a second century against Kenilworth",
      "Geoff Miller (Derbyshire, Essex, Natal and England) speaks at the annual dinner at Aston Wood Golf Club on Friday 26th January, and helps the President and James Ross present the awards",
