    yearOverview: "The optimism of a successful Annual Dinner in February was swiftly extinguished when the Covid-19 pandemic reached Britain, plunging the country into lockdown and cricket into silence. With no subscriptions coming in, no bar income and bills still to pay, the club faced a genuinely precarious position. President James Ross wrote personally to all Life Members and Vice Presidents, generating over £3,500 in donations, while Dave Hands secured a £7,000 Sport England grant and the joint clubs obtained a further £10,000 in hospitality support — a financial lifeline that carried Rectory Park through the storm. The pandemic's human cost struck close to home: young player Ben Dunnington lost his father Keith and, within weeks, both grandparents to the virus, a tragedy reported in the national press. When cricket finally resumed in a truncated regional format, Sutton's 1st XI finished mid-table in the Premier West group, while the Sunday side ran Wellesbourne close as runners-up in Arden Division 2. Lee Thomason was in imperious form, scoring 707 Sunday runs at an average of 101 with three centuries, and 558 Premier runs at 79.71. No fixture card was printed for the first time in living memory, yet the season ended in defiantly communal fashion, with a forty-strong working party — aged eight to sixty-six — clearing tonnes of autumn leaves before winter, rewarded with homemade cakes.",
