    yearOverview: "Sutton Coldfield Cricket Club celebrated 175 years of cricket at Rectory Park in fitting style. A year-long programme included a commemorative Golden Cask Ale brewed with the local Brewhouse & Kitchen, a Help for Heroes charity fixture, an over-35s tournament for the Andy Biddle Foundation, an anniversary Ball, and a rearranged April dinner where Test Match Special's Charles Dagnall entertained a hundred guests and the 175-year brochure was accepted into the MCC Library at Lord's. The cricket rose to the occasion. Over two April weekends 994 runs were scored on the same Rectory Park wicket, including a record-shattering 314 for 6 against Attock featuring a 203-run fifth-wicket stand between Raul Ram (95) and Aaron Thomason (114) — the highest home total, largest winning margin (211 runs) and best fifth-wicket partnership in club history. The 2nd XI provided the anniversary silverware, storming to the Division 5 championship with 352 points, while the 1st XI finished third in the Premier Division and the 4ths were runners-up in Division 9. The year also brought sadness with the deaths of Ken Lancaster, Martin Bloomer, Sid Stonehouse and Andy Thomas, and forward-looking governance, as the club adopted the ECB Anti-Discrimination Code of Conduct for all members. Crowdfunding delivered new sight screens, fencing, netting and a mower.",
